import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';

/// `MeusRegistrosScreen`'s permanently-docked search bar (spec-5-1,
/// Acceptance Criteria: "permanently docked at the top of Meus Registros
/// with a trailing funnel icon and is never submitted via a button") —
/// paper-elevated like `EntryRecordCard` (`colorSurfaceElevated`,
/// `radiusMd`, `elevation1`). [onChanged] feeds
/// `EntriesSearchCubit.onQueryChanged` directly on every keystroke — there
/// is no submit button anywhere on this widget, by design (Boundaries).
///
/// spec-5-2: the trailing funnel (`Icons.filter_list`) button now opens
/// the filter sheet via [onFilterTap] (`MeusRegistrosScreen`'s own
/// `EntriesFilterSheet.show()` call replaces the former no-op
/// `onPressed: () {}`) — still sized to the shared 44pt minimum tap
/// target (`insertionModalTapTargetMin`, UX-DR23). [hasActiveFilters]
/// fills it (`colorPrimary` instead of the resting `colorTextSecondary`)
/// whenever any filter is active (Boundaries: "fills the funnel icon").
class EntriesSearchBar extends StatelessWidget {
  const EntriesSearchBar({
    required this.onChanged,
    required this.onFilterTap,
    this.hasActiveFilters = false,
    super.key,
  });

  final ValueChanged<String> onChanged;

  /// spec-5-2 — opens the filter sheet.
  final VoidCallback onFilterTap;

  /// spec-5-2 — `true` whenever `MeusRegistrosCubit.hasActiveFilters` is
  /// true; defaults `false` so this widget still renders sensibly for any
  /// caller that has no filter state of its own to report.
  final bool hasActiveFilters;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusMd)),
        boxShadow: DesignTokens.elevation1,
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: DesignTokens.spacingMd),
        child: Row(
          children: [
            Expanded(
              child: TextField(
                onChanged: onChanged,
                style: DesignTokens.textBodyMd.copyWith(
                  color: DesignTokens.colorTextPrimary,
                ),
                decoration: InputDecoration(
                  isDense: true,
                  border: InputBorder.none,
                  hintText: 'Buscar nos registros...',
                  hintStyle: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                  contentPadding: const EdgeInsets.symmetric(
                    vertical: DesignTokens.spacingMd,
                  ),
                ),
              ),
            ),
            SizedBox(
              width: DesignTokens.insertionModalTapTargetMin,
              height: DesignTokens.insertionModalTapTargetMin,
              child: IconButton(
                padding: EdgeInsets.zero,
                onPressed: onFilterTap,
                // Review finding: an unlabeled icon-only button gives a
                // screen-reader user no indication of its purpose.
                // Round-2 review fix: also distinguishes "filters active"
                // for a screen-reader user, who otherwise has no way to
                // learn that beyond separately discovering the chip row.
                tooltip: hasActiveFilters ? 'Filtros (ativos)' : 'Filtros',
                icon: Icon(
                  Icons.filter_list,
                  color: hasActiveFilters
                      ? DesignTokens.colorPrimary
                      : DesignTokens.colorTextSecondary,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/widgets/app_button.dart';
import '../../domain/entities/date_range_preset.dart';
import '../../domain/entities/entry.dart';
import '../cubit/entries_search_cubit.dart';
import '../cubit/meus_registros_cubit.dart';

/// TIPO DE ENTRADA's own label for each [EntrySource]
/// (`prototype-extract.md` Tela 4 — Sheet de filtro) — shared by this
/// sheet's own chips and `MeusRegistrosScreen`'s active-filter chip row,
/// so the two surfaces never drift out of sync with each other (Code Map).
String entrySourceLabel(EntrySource source) => switch (source) {
  EntrySource.manual => 'Manual',
  EntrySource.audio => 'Áudio',
  EntrySource.photo => 'Foto',
  EntrySource.chat => 'Chat',
};

/// [DateRangePreset]'s own UI copy — kept out of the domain enum itself,
/// same split [entrySourceLabel] already gives [EntrySource]; shared by
/// this sheet's own chips and `MeusRegistrosScreen`'s active-filter chip
/// row.
String dateRangePresetLabel(DateRangePreset preset) => switch (preset) {
  DateRangePreset.allTime => 'Todo o período',
  DateRangePreset.thisWeek => 'Esta semana',
  DateRangePreset.thisMonth => 'Este mês',
};

/// The filter bottom sheet (spec-5-2) — two single-choice groups
/// ("INTERVALO DE DATA", "TIPO DE ENTRADA"; Design Notes: no "CATEGORIA"
/// group — the backend has no category filter, RF06) plus "Aplicar"/
/// "Limpar". Mirrors `InsertionModal.show()`'s own bottom-sheet
/// choreography (`isScrollControlled`, `useSafeArea`, `colorScrimHeavy`, a
/// Reduce-Motion-aware `durationSheetUp` entrance) — Code Map.
class EntriesFilterSheet extends StatefulWidget {
  const EntriesFilterSheet({
    required this.cubit,
    required this.searchCubit,
    super.key,
  });

  /// Passed in directly rather than read via `context.read` (same
  /// rationale `InsertionModal`'s own cubit constructor params give): a
  /// `showModalBottomSheet` route's `builder` context is inserted above
  /// `MeusRegistrosScreen`'s own `MultiBlocProvider`, not below it, so
  /// nothing that `BlocProvider` exposes would be reachable from here
  /// anyway.
  final MeusRegistrosCubit cubit;

  /// spec-5-3 — `MeusRegistrosScreen`'s own bridge to
  /// `EntriesSearchCubit` (Design Notes: the two cubits never import each
  /// other, RNF06); [_EntriesFilterSheetState._applyAndClose] calls
  /// [cubit]'s `applyFilters()` and this cubit's own `updateFilters()`
  /// side by side.
  final EntriesSearchCubit searchCubit;

  /// Presents the sheet exactly as the class doc describes. [cubit]'s own
  /// `applyFilters()` is called directly by this sheet's "Aplicar" button
  /// (`_EntriesFilterSheetState._applyAndClose`) — this `static` method
  /// itself never touches the cubit.
  static Future<void> show(
    BuildContext context, {
    required MeusRegistrosCubit cubit,
    required EntriesSearchCubit searchCubit,
  }) async {
    final reduceMotion = MediaQuery.of(context).disableAnimations;
    final controller =
        BottomSheet.createAnimationController(Navigator.of(context))
          ..duration = reduceMotion
              ? Duration.zero
              : DesignTokens.durationSheetUp
          ..reverseDuration = reduceMotion ? Duration.zero : null;
    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        barrierColor: DesignTokens.colorScrimHeavy,
        backgroundColor: Colors.transparent,
        elevation: 0,
        transitionAnimationController: controller,
        builder: (_) =>
            EntriesFilterSheet(cubit: cubit, searchCubit: searchCubit),
      );
    } finally {
      // Same "wait for the exit animation before disposing the
      // controller" rationale as `InsertionModal.show()`'s own `finally`
      // block (see its doc for the full explanation) — disposing the
      // moment `showModalBottomSheet`'s own `Future` resolves would cut
      // the still-running reverse animation's ticker off mid-flight.
      if (!controller.isDismissed) {
        final animationDone = Completer<void>();
        void onStatusChange(AnimationStatus status) {
          if (status == AnimationStatus.dismissed) {
            animationDone.complete();
          }
        }

        controller.addStatusListener(onStatusChange);
        await animationDone.future;
        controller.removeStatusListener(onStatusChange);
      }
      controller.dispose();
    }
  }

  @override
  State<EntriesFilterSheet> createState() => _EntriesFilterSheetState();
}

class _EntriesFilterSheetState extends State<EntriesFilterSheet> {
  late EntrySource? _pendingSource;
  late DateRangePreset _pendingDateRange;

  @override
  void initState() {
    super.initState();
    // Pre-selects whichever filters are already active — `docs/input/` is
    // silent on this exact behavior (AGENTS.md policy: "decide and
    // proceed") — rather than always reopening blank, so reopening the
    // sheet to tweak just one filter doesn't silently discard the other.
    // Round-2 review fix: reads the cubit's own stored preset directly
    // rather than re-deriving it from `activeDateFrom` by equality match —
    // that re-derivation went stale (mis-pre-selecting "Todo o período")
    // the moment a day/week/month boundary rolled over while the filter
    // stayed active.
    _pendingSource = widget.cubit.activeSource;
    _pendingDateRange = widget.cubit.activeDateRangePreset;
  }

  void _applyAndClose() {
    final (dateFrom, dateTo) = _pendingDateRange.rangeFrom(DateTime.now());
    widget.cubit.applyFilters(
      source: _pendingSource,
      dateFrom: dateFrom,
      dateTo: dateTo,
      dateRangePreset: _pendingDateRange,
    );
    // spec-5-3 — right alongside the existing `applyFilters()` call above:
    // a search that's currently active must carry this same filter
    // selection too (Boundaries), not just the plain/filtered timeline.
    widget.searchCubit.updateFilters(
      source: _pendingSource,
      dateFrom: dateFrom,
      dateTo: dateTo,
    );
    Navigator.of(context).pop();
  }

  /// "Limpar" (Boundaries: "resets only the sheet's own pending
  /// selection") — never touches [widget.cubit]/closes the sheet; that's
  /// `MeusRegistrosScreen`'s separate "Limpar filtros" link's own job
  /// (`MeusRegistrosCubit.clearFilters()`).
  void _clearPending() {
    setState(() {
      _pendingSource = null;
      _pendingDateRange = DateRangePreset.allTime;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: DesignTokens.screenPadding,
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(DesignTokens.radiusLg),
        ),
        boxShadow: DesignTokens.elevation2,
      ),
      child: SafeArea(
        top: false,
        // Epic-5 context's own UX note: "Filter chips and the search/
        // filter surfaces are a tight-fit area for Dynamic Type — verify
        // text does not truncate or clip at the largest accessibility
        // size" — a `SingleChildScrollView` guards against this sheet's
        // own content overflowing the screen at a large accessibility
        // text size, same safety net `InsertionModal`'s own tab content
        // already has (wrapped in its own `Flexible`/
        // `SingleChildScrollView` pair).
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                'INTERVALO DE DATA',
                style: DesignTokens.textMonoCaption.copyWith(
                  color: DesignTokens.colorTextSecondary,
                ),
              ),
              const SizedBox(height: DesignTokens.spacingSm),
              Wrap(
                spacing: DesignTokens.spacingSm,
                runSpacing: DesignTokens.spacingSm,
                children: [
                  for (final preset in DateRangePreset.values)
                    _FilterChip(
                      label: dateRangePresetLabel(preset),
                      selected: _pendingDateRange == preset,
                      onTap: () => setState(() => _pendingDateRange = preset),
                    ),
                ],
              ),
              const SizedBox(height: DesignTokens.spacingLg),
              Text(
                'TIPO DE ENTRADA',
                style: DesignTokens.textMonoCaption.copyWith(
                  color: DesignTokens.colorTextSecondary,
                ),
              ),
              const SizedBox(height: DesignTokens.spacingSm),
              Wrap(
                spacing: DesignTokens.spacingSm,
                runSpacing: DesignTokens.spacingSm,
                children: [
                  for (final source in EntrySource.values)
                    _FilterChip(
                      label: entrySourceLabel(source),
                      selected: _pendingSource == source,
                      // Single choice (Design Notes): unlike the date-range
                      // group above (whose 3 choices always include an
                      // explicit "none" — [DateRangePreset.allTime]),
                      // source has no dedicated "any source" chip — tapping
                      // the already-selected one toggles it back off
                      // instead of being a no-op, since that's otherwise
                      // the only way to clear just this one group without
                      // "Limpar" resetting the date group too.
                      onTap: () => setState(
                        () => _pendingSource = _pendingSource == source
                            ? null
                            : source,
                      ),
                    ),
                ],
              ),
              const SizedBox(height: DesignTokens.spacingLg),
              Row(
                children: [
                  Expanded(
                    child: AppButton(
                      label: 'Limpar',
                      variant: AppButtonVariant.textGhost,
                      onPressed: _clearPending,
                    ),
                  ),
                  const SizedBox(width: DesignTokens.spacingMd),
                  Expanded(
                    child: AppButton(
                      label: 'Aplicar',
                      onPressed: _applyAndClose,
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// One selectable group option — reused by both groups ("INTERVALO DE
/// DATA"/"TIPO DE ENTRADA"); selected state is `colorSecondary` fill +
/// `colorCategoryChipText` text, same token pair the active-filter chip
/// row (`MeusRegistrosScreen`) reuses for its own chips (Boundaries: exact
/// token reuse, no new token). Unselected state is a plain `colorBorder`
/// outline — not itself named by Boundaries, since only the *selected*
/// look is actually specified there.
class _FilterChip extends StatelessWidget {
  const _FilterChip({
    required this.label,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      selected: selected,
      label: label,
      excludeSemantics: true,
      child: InkWell(
        borderRadius: const BorderRadius.all(
          Radius.circular(DesignTokens.radiusFull),
        ),
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(
            horizontal: DesignTokens.spacingMd,
            vertical: DesignTokens.spacingSm,
          ),
          decoration: BoxDecoration(
            color: selected
                ? DesignTokens.colorSecondary
                : DesignTokens.colorSurfaceBg,
            borderRadius: const BorderRadius.all(
              Radius.circular(DesignTokens.radiusFull),
            ),
            border: selected
                ? null
                : Border.all(
                    color: DesignTokens.colorBorder,
                    width: DesignTokens.borderWidthDefault,
                  ),
          ),
          child: Text(
            label,
            style: DesignTokens.textLabelMd.copyWith(
              color: selected
                  ? DesignTokens.colorCategoryChipText
                  : DesignTokens.colorTextPrimary,
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../domain/entities/entry.dart';
import '../../domain/entities/sync_badge_state.dart';
import 'sync_badge.dart';

/// One origin's icon + spine color — `cerne-prototype.html`'s own
/// `sourceMeta` object (Boundaries: "exact hex match"): manual `#1F3D34`
/// (`colorPrimary`), audio `#7C8B6F` (`colorSecondary`), photo `#6B6255`
/// (`colorTextSecondary`), chat `#C98A3E` (`colorAccent`) — all four already
/// exist in `design_tokens.dart`, so this story adds no new color. Icons are
/// built-in Material equivalents of the prototype's Phosphor glyphs (no
/// Phosphor dependency in this project — same approximation rationale
/// `DesignTokens.dialogIconSize`'s doc already gives), each already used
/// elsewhere in the app for the same origin: `Icons.mic`
/// (`insertion_modal.dart`'s Áudio tab), `Icons.image_outlined`
/// (its Foto tab), `Icons.chat_bubble_outline`
/// (`HomeChatPlaceholderScreen`'s own chat icon).
class _SourceMeta {
  const _SourceMeta(this.icon, this.color);

  final IconData icon;
  final Color color;
}

const _sourceMeta = <EntrySource, _SourceMeta>{
  EntrySource.manual: _SourceMeta(
    Icons.edit_outlined,
    DesignTokens.colorPrimary,
  ),
  EntrySource.audio: _SourceMeta(Icons.mic, DesignTokens.colorSecondary),
  EntrySource.photo: _SourceMeta(
    Icons.image_outlined,
    DesignTokens.colorTextSecondary,
  ),
  EntrySource.chat: _SourceMeta(
    Icons.chat_bubble_outline,
    DesignTokens.colorAccent,
  ),
};

/// `MeusRegistrosScreen`'s one record card — mirrors
/// `placeholder_screens.dart`'s `_KanbanCard` structure (colored left
/// spine over a `Stack`, Code Map) but for an [Entry]: spine colored by
/// [Entry.source], a source icon, the local time, a content excerpt, and
/// (spec-4-2) its own [SyncBadge]. spec-4-4: [onTap] is this card's one
/// navigation affordance — it opens `EntryDetailScreen`
/// (`MeusRegistrosScreen`'s own wiring), scoped to the card's body; the
/// only other `InkWell` anywhere in this subtree still lives inside
/// [SyncBadge] itself, scoped to the badge's own tap target, so a tap
/// landing on the badge triggers retry, never navigation.
class EntryRecordCard extends StatelessWidget {
  const EntryRecordCard({
    required this.entry,
    required this.badgeState,
    required this.onTap,
    this.onRetryTap,
    super.key,
  });

  final Entry entry;

  /// This card's own badge (Code Map: `deriveSyncBadgeState()`'s result)
  /// — computed by the caller (`MeusRegistrosLoaded.badgeFor`), never
  /// recomputed here (Never: "any screen recomputing badge state inline").
  final SyncBadgeState badgeState;

  /// spec-4-4 — opens this entry's detail view
  /// (`MeusRegistrosScreen`'s `context.push('${AppRoutePaths.
  /// meusRegistros}/${Uri.encodeComponent(entry.id)}')` — the id is
  /// URL-encoded, round-1 review fix). A pending/failed placeholder's own
  /// synthetic `tempId` is a valid, un-special-cased target here too
  /// (Boundaries) — this card never knows or cares which kind of id it
  /// holds.
  final VoidCallback onTap;

  /// Forwarded to [SyncBadge] verbatim — only ever invoked for a
  /// retryable [SyncBadgeError].
  final VoidCallback? onRetryTap;

  @override
  Widget build(BuildContext context) {
    final meta = _sourceMeta[entry.source]!;
    final time = _formatTime(entry.occurredAt);

    return DecoratedBox(
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusMd)),
        boxShadow: DesignTokens.elevation1,
      ),
      child: ClipRRect(
        borderRadius: const BorderRadius.all(
          Radius.circular(DesignTokens.radiusMd),
        ),
        // Review finding, round 1: the tappable area must cover the whole
        // card — including the colored spine strip beside the content, not
        // just the content `Padding` — so `Material`/`InkWell` now wraps
        // the entire `Stack` rather than only its second child.
        // `SyncBadge`'s own nested `InkWell` still wins the hit test for a
        // tap landing on the badge itself.
        child: Material(
          type: MaterialType.transparency,
          child: InkWell(
            onTap: onTap,
            child: Stack(
              children: [
                Positioned(
                  left: 0,
                  top: 0,
                  bottom: 0,
                  width: DesignTokens.kanbanCardSpineWidth,
                  child: ColoredBox(color: meta.color),
                ),
                Padding(
                  padding: DesignTokens.kanbanCardPadding,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Row(
                        children: [
                          Icon(meta.icon, color: meta.color),
                          const SizedBox(width: DesignTokens.spacingSm),
                          Text(
                            time,
                            style: DesignTokens.textMonoCaption.copyWith(
                              color: DesignTokens.colorTextSecondary,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: DesignTokens.spacingXs),
                      Text(
                        entry.content,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: DesignTokens.textBodyMd.copyWith(
                          color: DesignTokens.colorTextPrimary,
                        ),
                      ),
                      const SizedBox(height: DesignTokens.spacingXs),
                      SyncBadge(state: badgeState, onRetryTap: onRetryTap),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

/// `occurredAt`'s local wall-clock time, `HH:mm` — presentation's own
/// formatting job (Code Map: `Entry.occurredAt` stays a raw ISO string,
/// "parsed only for grouping" at the domain layer; this is the analogous
/// parse-for-display step, scoped to this one widget). A malformed
/// [occurredAt] returns the `'--:--'` placeholder instead of throwing
/// (RNF09), same defensive rationale `groupEntriesByDate()`'s own guard
/// uses.
String _formatTime(String occurredAt) {
  final local = DateTime.tryParse(occurredAt)?.toLocal();
  if (local == null) {
    return '--:--';
  }
  final hour = local.hour.toString().padLeft(2, '0');
  final minute = local.minute.toString().padLeft(2, '0');
  return '$hour:$minute';
}

import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';
import '../../domain/entities/sync_badge_state.dart';

/// `EntryRecordCard`'s own sync badge (Code Map) — a colored dot
/// ([DesignTokens.colorWarningSync]/[DesignTokens.colorSuccess]/
/// [DesignTokens.colorError]) plus its text label, always visible (not
/// hidden behind a tap). "Accessible label on tap/long-focus" is split
/// across two single-purpose widgets rather than two that both also
/// announce it: the dot's [Tooltip] (`excludeFromSemantics: true`) gives
/// the *visual* long-press popup only, while the one [Semantics] node
/// wrapping the whole badge (below) is the single accessibility
/// announcement on focus — code-review round 1 finding: a [Tooltip] left
/// at its default `excludeFromSemantics: false` injects its own semantics
/// label too, so pairing it with an outer [Semantics] of the same label
/// double-announced it to screen readers.
///
/// Only an [SyncBadgeError] badge is ever tappable (Boundaries): a
/// [Failure.retryable] one calls [onRetryTap] on tap (I/O matrix: "Tap
/// calls `tracker.retry(tempId)`, re-sends same payload"); a
/// non-retryable one instead toggles an inline explanation
/// ([SyncBadgeError.failure]'s own `message`) with no network call and no
/// retry affordance (Boundaries: "else render inline explanation text, no
/// tap affordance"). [SyncBadgeSynchronizing]/[SyncBadgeSynchronized] are
/// never tappable at all.
class SyncBadge extends StatefulWidget {
  const SyncBadge({required this.state, this.onRetryTap, super.key});

  final SyncBadgeState state;

  /// Called on tap only for a retryable [SyncBadgeError] — ignored (never
  /// even referenced) for every other state, and for a non-retryable
  /// error (Boundaries: "no tap affordance" there means no retry action,
  /// not no tap at all — tapping a non-retryable error still reveals its
  /// explanation, just never calls this).
  final VoidCallback? onRetryTap;

  @override
  State<SyncBadge> createState() => _SyncBadgeState();
}

class _SyncBadgeState extends State<SyncBadge> {
  bool _explanationExpanded = false;

  @override
  void didUpdateWidget(SyncBadge oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A retry attempt (or any other state transition) collapses a
    // previously-shown explanation — stale text from a superseded
    // failure should never linger once the badge has moved on (e.g.
    // synchronizing -> a *new* error after a retry that fails again).
    if (widget.state != oldWidget.state) {
      _explanationExpanded = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    final state = widget.state;
    final (color, label) = switch (state) {
      SyncBadgeSynchronizing() => (
        DesignTokens.colorWarningSync,
        'Sincronizando',
      ),
      SyncBadgeSynchronized() => (DesignTokens.colorSuccess, 'Sincronizado'),
      SyncBadgeError() => (DesignTokens.colorError, 'Erro de sincronização'),
    };

    // Reuses the existing kanban color-dot token (8dp) rather than a new
    // literal (RNF08) — same shape/role (a small colored status dot), just
    // a different screen. `excludeFromSemantics: true` (Review finding):
    // the outer `Semantics(label: label)` below is this badge's one and
    // only accessibility announcement — this Tooltip exists purely for
    // its own visual long-press popup.
    final dot = Tooltip(
      message: label,
      excludeFromSemantics: true,
      child: Container(
        width: DesignTokens.kanbanDotSize,
        height: DesignTokens.kanbanDotSize,
        decoration: BoxDecoration(color: color, shape: BoxShape.circle),
      ),
    );

    // `ExcludeSemantics` (Review finding): without it, the visible `Text`
    // below contributes its *own* implicit semantics label ("Sincronizando",
    // same string) that merges straight into the explicit `Semantics(label:
    // label)` container wrapping this whole row — doubling the announced
    // label even after the dot's own `Tooltip` was already excluded above.
    // The one `Semantics(label: label)` node is this badge's single source
    // of truth for its accessible text; this row is purely visual.
    final labelRow = ExcludeSemantics(
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          dot,
          const SizedBox(width: DesignTokens.spacingXs),
          Text(
            label,
            style: DesignTokens.textMonoCaption.copyWith(color: color),
          ),
        ],
      ),
    );

    if (state is! SyncBadgeError) {
      // `container: true` (Review finding) — without it, a `Semantics`
      // widget with no interactive descendant doesn't form its own node;
      // Flutter merges its `label` up into the nearest explicit container
      // ancestor instead (e.g. the Scaffold's own), so `label` alone is
      // never exactly what a screen reader (or `find.bySemanticsLabel`)
      // reports for this widget specifically.
      return Semantics(label: label, container: true, child: labelRow);
    }

    final retryable = state.failure.retryable;
    return Semantics(
      label: label,
      container: true,
      button: true,
      child: InkWell(
        onTap: () {
          if (retryable) {
            widget.onRetryTap?.call();
          } else {
            setState(() => _explanationExpanded = !_explanationExpanded);
          }
        },
        child: ConstrainedBox(
          constraints: const BoxConstraints(
            minWidth: DesignTokens.insertionModalTapTargetMin,
            minHeight: DesignTokens.insertionModalTapTargetMin,
          ),
          child: Align(
            alignment: Alignment.centerLeft,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                labelRow,
                if (!retryable && _explanationExpanded)
                  Padding(
                    padding: const EdgeInsets.only(top: DesignTokens.spacingXs),
                    child: Text(
                      state.failure.message,
                      style: DesignTokens.textCaptionSm.copyWith(
                        color: DesignTokens.colorTextSecondary,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

