318	/// spec-5-1's own search-results surface — `EntriesSearchCubit`'s
319	/// `Resource<List<Entry>>` rendered in place of the timeline whenever
320	/// [state] isn't `ResourceIdle` (the screen's own `build` filters that
321	/// variant out before ever reaching here). Every result here is always a
322	/// server-confirmed [Entry] (`EntriesRepository.search()`'s own contract —
323	/// no cache fallback, no pending-write overlay), so every card's badge is
324	/// unconditionally [SyncBadgeState.synchronized] — never recomputed via
325	/// `deriveSyncBadgeState()` (Never: "any screen recomputing badge state
326	/// inline" extends here too, there is simply no pending/offline state for
327	/// a search result to derive).
328	class _SearchResults extends StatelessWidget {
329	  const _SearchResults({
330	    required this.state,
331	    required this.showSkeleton,
332	    required this.onCardTap,
333	  });
334	
335	  final Resource<List<Entry>> state;
336	  final bool showSkeleton;
337	  final void Function(Entry entry) onCardTap;
338	
339	  @override
340	  Widget build(BuildContext context) {
341	    return switch (state) {
342	      ResourceIdle<List<Entry>>() =>
343	        // Unreachable — `MeusRegistrosScreen.build` never routes
344	        // `ResourceIdle` here — kept only so this switch stays exhaustive.
345	        const SizedBox.shrink(),
346	      ResourceLoading<List<Entry>>() =>
347	        showSkeleton ? const _SkeletonList() : const SizedBox.shrink(),
348	      ResourceError<List<Entry>>(failure: final failure) => _SearchErrorState(
349	        message: failure.message,
350	      ),
351	      ResourceData<List<Entry>>(data: final entries) =>
352	        entries.isEmpty
353	            ? const _EmptySearchResults()
354	            : ListView.builder(
355	                padding: DesignTokens.screenPadding,
356	                itemCount: entries.length,
357	                itemBuilder: (context, index) {
358	                  final entry = entries[index];
359	                  return Padding(
360	                    key: ValueKey(entry.id),
361	                    padding: const EdgeInsets.only(
362	                      bottom: DesignTokens.spacingSm,
363	                    ),
364	                    child: EntryRecordCard(
365	                      entry: entry,
366	                      badgeState: const SyncBadgeState.synchronized(),
367	                      onTap: () => onCardTap(entry),
368	                    ),
369	                  );
370	                },
371	              ),
372	    };
373	  }
