587	  final EntryDateGroup group;
588	
589	  /// `MeusRegistrosLoaded.badgeFor` — the one call site outside the
590	  /// cubit/state itself (Never: "any screen recomputing badge state
591	  /// inline").
592	  final SyncBadgeState Function(Entry entry) badgeFor;
593	
594	  /// `MeusRegistrosCubit.retry`, pre-bound to this entry's own id —
595	  /// `EntryRecordCard`/`SyncBadge` only ever call this for a retryable
596	  /// error badge.
597	  final void Function(Entry entry) onRetryTap;
598	
599	  /// spec-4-4 — `EntryRecordCard`'s own `onTap`, pre-bound to this entry's
600	  /// own id.
601	  final void Function(Entry entry) onCardTap;
602	
603	  @override
604	  Widget build(BuildContext context) {
605	    return Padding(
606	      padding: const EdgeInsets.only(bottom: DesignTokens.spacingMd),
607	      child: Column(
608	        crossAxisAlignment: CrossAxisAlignment.start,
609	        children: [
610	          Text(
611	            _dayLabel(group.date),
612	            style: DesignTokens.textTitleSm.copyWith(
613	              color: DesignTokens.colorTextPrimary,
614	            ),
615	          ),
616	          const SizedBox(height: DesignTokens.spacingSm),
617	          for (final entry in group.entries) ...[
618	            EntryRecordCard(
619	              key: ValueKey(entry.id),
620	              entry: entry,
621	              badgeState: badgeFor(entry),
622	              onTap: () => onCardTap(entry),
623	              onRetryTap: () => onRetryTap(entry),
624	            ),
625	            const SizedBox(height: DesignTokens.spacingSm),
626	          ],
627	        ],
628	      ),
629	    );
630	  }
631	}
632	
633	class _LoadMoreFooter extends StatelessWidget {
634	  const _LoadMoreFooter({
635	    required this.hasMore,
636	    required this.isLoading,
637	    required this.failed,
638	    required this.onRetry,
639	  });
640	
641	  final bool hasMore;
642	  final bool isLoading;
643	  final bool failed;
644	  final VoidCallback onRetry;
645	
646	  @override
647	  Widget build(BuildContext context) {
648	    if (failed) {
649	      return Padding(
650	        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
651	        child: Center(
652	          child: TextButton(
653	            onPressed: onRetry,
654	            child: Text(
655	              'Tentar novamente',
656	              style: DesignTokens.textLabelMd.copyWith(
657	                color: DesignTokens.colorPrimary,
658	              ),
659	            ),
660	          ),
661	        ),
662	      );
663	    }
664	    if (isLoading) {
665	      return const Padding(
666	        padding: EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
667	        child: Center(
668	          child: CircularProgressIndicator(color: DesignTokens.colorPrimary),
669	        ),
670	      );
671	    }
672	    return const SizedBox.shrink();
673	  }
674	}
675	
676	/// spec-5-2 — the active-filter chip row rendered under the search bar
677	/// whenever `MeusRegistrosCubit.hasActiveFilters` is true (Boundaries);
678	/// reads the cubit's own filter fields directly rather than threading them
679	/// through `MeusRegistrosState` (Design Notes: a filter change already
680	/// re-emits a new state via `applyFilters()`/`clearFilters()`, so this
681	/// widget's own `BlocBuilder` ancestor already rebuilds it in lockstep).
682	class _ActiveFiltersRow extends StatelessWidget {
683	  const _ActiveFiltersRow({required this.cubit, required this.searchCubit});
684	
685	  final MeusRegistrosCubit cubit;
686	
687	  /// spec-5-3 — `MeusRegistrosScreen`'s own bridge to
688	  /// `EntriesSearchCubit` (Design Notes): every filter-mutating call site
689	  /// below also calls this cubit's own `updateFilters()`, right alongside
690	  /// [cubit]'s `applyFilters()`/`clearFilters()`, so a filter change
691	  /// during an active search is reflected there too.
692	  final EntriesSearchCubit searchCubit;
693	
694	  @override
695	  Widget build(BuildContext context) {
696	    final source = cubit.activeSource;
697	    final dateFrom = cubit.activeDateFrom;
698	    final dateTo = cubit.activeDateTo;
699	    final dateRangePreset = cubit.activeDateRangePreset;
700	    final hasDateRange = dateFrom != null && dateTo != null;
701	    return Padding(
702	      padding: const EdgeInsets.fromLTRB(
703	        DesignTokens.spacingMd,
704	        DesignTokens.spacingSm,
705	        DesignTokens.spacingMd,
706	        0,
707	      ),
708	      child: Wrap(
709	        crossAxisAlignment: WrapCrossAlignment.center,
710	        spacing: DesignTokens.spacingSm,
711	        runSpacing: DesignTokens.spacingSm,
712	        children: [
713	          if (source != null)
714	            _ActiveFilterChip(
715	              label: entrySourceLabel(source),
716	              // I/O matrix: "Remove one of two active chips" — re-applies
717	              // every *other* active filter exactly as it stood, dropping
718	              // only this one. Round-2 review fix: passes `dateRangePreset`
719	              // back in too — otherwise the still-active date range would
720	              // revert to the cubit's default "Todo o período" preset.
721	              onRemove: () {
722	                cubit.applyFilters(
723	                  dateFrom: dateFrom,
724	                  dateTo: dateTo,
725	                  dateRangePreset: dateRangePreset,
726	                );
727	                searchCubit.updateFilters(dateFrom: dateFrom, dateTo: dateTo);
728	              },
729	            ),
730	          if (hasDateRange)
731	            _ActiveFilterChip(
732	              label: dateRangePresetLabel(dateRangePreset),
733	              onRemove: () {
734	                cubit.applyFilters(source: source);
735	                searchCubit.updateFilters(source: source);
736	              },
737	            ),
738	          AppButton(
739	            variant: AppButtonVariant.textGhost,
740	            label: 'Limpar filtros',
741	            // I/O matrix: "Clear all filters" — restores the full
742	            // unfiltered list in place, no reload/re-mount (Boundaries).
743	            onPressed: () {
744	              cubit.clearFilters();
745	              searchCubit.updateFilters();
746	            },
747	          ),
748	        ],
749	      ),
750	    );
751	  }
752	}
753	
754	/// One removable active-filter chip — `colorSecondary`/
755	/// `colorCategoryChipText`/`radiusFull` (Boundaries: exact token reuse,
756	/// no new token).
757	class _ActiveFilterChip extends StatelessWidget {
758	  const _ActiveFilterChip({required this.label, required this.onRemove});
759	
760	  final String label;
761	  final VoidCallback onRemove;
762	
763	  @override
764	  Widget build(BuildContext context) {
765	    return Semantics(
766	      button: true,
767	      label: '$label, remover filtro',
768	      excludeSemantics: true,
769	      child: InkWell(
770	        borderRadius: const BorderRadius.all(
771	          Radius.circular(DesignTokens.radiusFull),
772	        ),
773	        onTap: onRemove,
774	        child: Container(
775	          padding: const EdgeInsets.symmetric(
776	            horizontal: DesignTokens.spacingMd,
777	            vertical: DesignTokens.spacingXs,
778	          ),
779	          decoration: const BoxDecoration(
780	            color: DesignTokens.colorSecondary,
781	            borderRadius: BorderRadius.all(
782	              Radius.circular(DesignTokens.radiusFull),
783	            ),
784	          ),
785	          child: Row(
786	            mainAxisSize: MainAxisSize.min,
787	            children: [
788	              Text(
789	                label,
790	                style: DesignTokens.textLabelMd.copyWith(
791	                  color: DesignTokens.colorCategoryChipText,
792	                ),
793	              ),
794	              const SizedBox(width: DesignTokens.spacingXs),
795	              const Icon(
796	                Icons.close,
797	                color: DesignTokens.colorCategoryChipText,
798	              ),
799	            ],
800	          ),
801	        ),
802	      ),
803	    );
804	  }
805	}
806	
807	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
808	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
809	/// always already truncated to local midnight (`EntryDateGroup`'s own
810	/// contract).
811	String _dayLabel(DateTime date) {
812	  final now = DateTime.now();
813	  final today = DateTime(now.year, now.month, now.day);
814	  final yesterday = today.subtract(const Duration(days: 1));
815	  if (date == today) {
816	    return 'Hoje';
817	  }
818	  if (date == yesterday) {
819	    return 'Ontem';
820	  }
821	  final day = date.day.toString().padLeft(2, '0');
822	  final month = date.month.toString().padLeft(2, '0');
823	  return '$day/$month/${date.year}';
824	}
