    expect(call.query, 'ansiedade');
    expect(call.source, EntrySource.audio);
    expect(call.dateFrom, isNull);
    expect(find.text('Áudio'), findsOneWidget);
    expect(find.text('Este mês'), findsNothing);
  });

  testWidgets(
