                    child: Text(
                      state.failure.message,
                      style: DesignTokens.textCaptionSm.copyWith(
                        color: DesignTokens.colorTextSecondary,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

